import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DMtjdCb-.js";const u=JSON.parse('{"title":"10. Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/troubleshooting.md","filePath":"en/troubleshooting.md"}'),i={name:"en/troubleshooting.md"};function s(r,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_10-troubleshooting" tabindex="-1">10. Troubleshooting <a class="header-anchor" href="#_10-troubleshooting" aria-label="Permalink to &quot;10. Troubleshooting&quot;">​</a></h1><p>Start with the symptom you see. Retry the original action after each check, so that each change has a clear result.</p><h2 id="open-page" tabindex="-1">The page will not open <a class="header-anchor" href="#open-page" aria-label="Permalink to &quot;The page will not open {#open-page}&quot;">​</a></h2><ol><li>Keep the desktop startup window running, or check that the Docker container is running.</li><li>Use the address and port shown in its startup log.</li><li>On a phone, replace <code>localhost</code> with the runtime device&#39;s LAN address.</li><li>If a port is occupied, select another one using the <a href="./docker.html">deployment steps</a>, then restart.</li></ol><h2 id="i-cannot-find-the-password" tabindex="-1">I cannot find the password <a class="header-anchor" href="#i-cannot-find-the-password" aria-label="Permalink to &quot;I cannot find the password&quot;">​</a></h2><p>Check the first startup window or container log. The desktop package saves the initial account in <code>data/state/auth/initial-admin.txt</code>; the default Docker stack uses the same path under its project folder. If you changed the password, use that account; another administrator can assist with account management.</p><h2 id="titles-or-covers-have-not-appeared" tabindex="-1">Titles or covers have not appeared <a class="header-anchor" href="#titles-or-covers-have-not-appeared" aria-label="Permalink to &quot;Titles or covers have not appeared&quot;">​</a></h2><p>The first start prepares recent titles before the complete catalog and remaining images. Check the home-page progress and <strong>Settings → Diagnostics</strong>. Downloads retry after connectivity recovers. Search older titles again once the full catalog is ready.</p><h2 id="download" tabindex="-1">A resource was found but nothing is downloading <a class="header-anchor" href="#download" aria-label="Permalink to &quot;A resource was found but nothing is downloading {#download}&quot;">​</a></h2><ol><li>Check that you selected a release and confirmed its subscription or download plan.</li><li>Check Ani-RSS / qBittorrent in <strong>Settings → Connections</strong>.</li><li>In the downloader, check whether the task exists, its destination is available, and peers can be reached.</li><li>If Torrent results are collapsed, expand them before selecting a group and variant.</li></ol><h2 id="existing-files-cannot-be-played" tabindex="-1">Existing files cannot be played <a class="header-anchor" href="#existing-files-cannot-be-played" aria-label="Permalink to &quot;Existing files cannot be played&quot;">​</a></h2><ol><li>Confirm the media folder is readable in <strong>Settings → Connections</strong>.</li><li>In Docker, mount the NAS folder first, then enter its container path.</li><li>Let the inventory finish and select the source that contains the media.</li><li>Check main-episode classification and title/episode names. See <a href="./collections.html">Existing collections</a>.</li></ol><h2 id="the-player-does-not-open-or-reports-a-bad-address" tabindex="-1">The player does not open or reports a bad address <a class="header-anchor" href="#the-player-does-not-open-or-reports-a-bad-address" aria-label="Permalink to &quot;The player does not open or reports a bad address&quot;">​</a></h2><ol><li>Install the player on your current device and allow the browser to open external apps.</li><li>Copy the playlist into the player, or download the playlist file.</li><li>Use an AnimeMachine address reachable from the player; <code>localhost</code> from another device points to that device.</li><li>Generate a fresh playlist if the old one expired or new episodes arrived.</li></ol><p>The PotPlayer extension saves precise positions on Windows. VLC and ordinary media access record episodes; use <a href="./continue-watching.html#correct">viewing records</a> to correct a mistaken inference.</p><h2 id="continue-watching-is-empty" tabindex="-1">Continue watching is empty <a class="header-anchor" href="#continue-watching-is-empty" aria-label="Permalink to &quot;Continue watching is empty&quot;">​</a></h2><p>Check that the season contains subscribed TV titles whose latest episode is unfinished and whose media is playable. Paused, unsubscribed, hidden, and completed-latest titles are excluded from a new playlist.</p><h2 id="which-log-messages-need-attention" tabindex="-1">Which log messages need attention? <a class="header-anchor" href="#which-log-messages-need-attention" aria-label="Permalink to &quot;Which log messages need attention?&quot;">​</a></h2><p>In <strong>Settings → Logs</strong>, filter to warnings and errors around the time of the action. For a persistent issue, note the app version, deployment method, steps, and relevant error. Remove passwords, keys, and personal paths before sharing logs or screenshots.</p>',19)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
